-- FAQ revamp: one well-organised set of answers to the questions families actually ask,
-- matching the prospectus (v5, October 2026): Year 1 to 11, launch Monday 7 December 2026,
-- fees and payment dates, exam boards, open evenings. Two new categories (School day,
-- Safeguarding). Replaces the previous entries wholesale; admins edit them in Content.
alter table public.faq_entries drop constraint if exists faq_entries_category_check;
alter table public.faq_entries add constraint faq_entries_category_check check (category in ('Admissions', 'School day', 'Fees', 'Curriculum', 'Islamic Studies', 'Technology', 'SEND', 'Safeguarding'));
delete from public.faq_entries;
