insert into public.faq_entries (category, order_index, question, answer) values
  ('Admissions', 1, 'When do live lessons start, and what is the deadline to apply?', 'Live lessons start on Monday 7 December 2026. Applications for a December start close on Friday 27 November 2026, and every new pupil joins an online induction week from 30 November to 4 December, so they know their teachers, their timetable and the portal before the first lesson. Applications received after the deadline are considered for a January start.'),
  ('Admissions', 2, 'Which year groups can apply?', 'Year 1 to Year 11 (ages 5 to 16 on 31 August 2026). We do not run Reception. Year group is set by age in the normal English way; if you are not sure which year your child falls into, the application works it out from their date of birth.'),
  ('Admissions', 3, 'How do I apply, step by step?', '1) Register for an open evening or book a call if you want to talk to us first. 2) Complete the online application (about 15 minutes) and pay the {{applicationFee}} application fee. 3) Your child sits a short online entry assessment and we have a conversation with you. 4) We offer a place in writing. 5) You accept by paying the {{registrationFee}} registration fee and signing the parent agreement on the portal. 6) Induction week, then lessons begin.'),
  ('Admissions', 4, 'What is the entry assessment like?', 'It is short, age-appropriate and online: a reading and maths check, a few minutes of Qur''an reading or recitation at whatever level your child is at, and a friendly conversation. It is used to place your child in the right Qur''an and Arabic group and to plan support, not to turn children away. Nothing needs revising for it.'),
  ('Admissions', 5, 'Can we see the school before we commit?', 'Yes. We are holding two online open evenings — Thursday 12 November at 7:30pm and Sunday 15 November at 4:00pm (UK time) — where you meet the Headteacher and teachers and ask anything. There is also a taster morning on Saturday 14 November: Years 1 to 6 at 10:00 and Years 7 to 11 at 11:15, where your child joins a real live lesson. Register from the Open evenings page; the joining link and a calendar invite are emailed to you.'),
  ('Admissions', 6, 'Can we apply from outside the UK?', 'Yes. Lessons run 09:00 to 15:00 UK time, so the Academy works well for families in the UK, Europe, North and West Africa, Turkey and the Middle East. Check the timings in your own time zone with the two-minute Is TGA right for us? check before you apply.'),
  ('Admissions', 7, 'Can my child join part-way through the year?', 'Yes, where there is a place in the year group. The same application, assessment and induction steps apply, and fees are adjusted for the part of the year your child attends.'),
  ('Admissions', 8, 'What is the difference between registering interest and applying?', 'Registering interest is a short form so we can keep you updated and invite you to events; it commits you to nothing. Applying is the full application with the {{applicationFee}} fee, and starts the admissions process.'),
  ('School day', 1, 'What are the school hours?', 'Monday to Thursday, 09:00 to 15:00 UK time; Fridays, 09:00 to 12:00 so families can prepare for Jumu''ah. The day opens with ten minutes of form time at 09:00 and lessons start at 09:10. Dhuhr is built into the timetable.'),
  ('School day', 2, 'How long are lessons, and how big are the classes?', 'Lessons are live and taught by a qualified teacher to a class of no more than 15. Younger pupils have shorter sessions with movement breaks; older pupils have longer lessons. Each key stage''s curriculum page shows a sample week.'),
  ('School day', 3, 'Is my child on a screen all day?', 'No. Live lessons are broken up with independent tasks, reading, writing by hand, prayer and movement breaks, and Friday afternoons are off-screen. Homework is set to be manageable and is tracked on the portal so nothing is lost.'),
  ('School day', 4, 'Does a parent need to be at home during lessons?', 'For Years 1 to 3, an adult should be nearby to help with logging in and staying on task; from Year 4 most pupils manage independently once settled, and from Year 7 we expect it. Every lesson is recorded on the register, so you know your child was there.'),
  ('School day', 5, 'What does my child do if they are unwell or miss a lesson?', 'Tell us through the Parent Portal or by email before 09:00 and we record an authorised absence. Lesson resources and homework stay on the portal, and the teacher will help your child catch up.'),
  ('School day', 6, 'Are there term dates and holidays?', 'Yes. Term dates are published on the Admissions page and in the portal calendar: lessons start on Monday 7 December 2026 and the year runs to July 2027 with half-term breaks and Eid holidays marked.'),
  ('Fees', 1, 'How much are the fees?', 'For December 2026 to July 2027: Years 1–2 £1,710; Years 3–6 £2,282; Years 7–9 £2,996; Years 10–11 £3,214. These are the full amounts for the period, include 20% VAT, and cover all tuition and digital learning materials. There are no hidden extras.'),
  ('Fees', 2, 'What are the application and registration fees, and why?', 'The application fee is {{applicationFee}} and pays for the entry assessment and the time we spend with each family. The registration fee is {{registrationFee}} per child ({{registrationFee}} for the first child and half that for each additional sibling), paid once when you accept a place; it secures the place and sets up your child''s accounts, portal and resources. Neither is refundable.'),
  ('Fees', 3, 'How can we pay?', 'Three ways, all adding up to the same annual total: in full by 4 December 2026 with a {{annualDiscount}} discount; in two termly payments (4 December and 28 March); or in eight monthly payments (4 December, then the 28th of each month from December to June). Pay by bank transfer, standing order or card. Your plan is chosen on the portal when you accept.'),
  ('Fees', 4, 'Is there a sibling discount?', 'Yes: 5% off tuition for a second child and 10% off for a third or further child, applied automatically to the lower fees. The registration fee for each additional sibling is also halved.'),
  ('Fees', 5, 'What is not included in the fees?', 'GCSE and International GCSE exam entry fees, which are paid directly to the exam centre; any printed textbooks or stationery you choose to buy; and your own device and internet connection.'),
  ('Fees', 6, 'Is there a probationary period?', 'Yes. Every new pupil joins on a probationary basis for their first half term, so both the family and the Academy can judge whether online learning at TGA is right for the child. Progress is monitored closely with regular feedback during that time.'),
  ('Fees', 7, 'What happens if we withdraw or miss a payment?', 'One half term''s written notice is required to withdraw a pupil, using the Withdrawal Form on the website, and fees remain payable for the notice period. If a payment is missed you are given 14 days'' written notice to pay before anything else happens; the Fees Policy on the Policies page sets out the full process, refunds and the 14-day cancellation right.'),
  ('Curriculum', 1, 'What does my child study?', 'Three strands every week: Qur''an, Arabic and Islamic Studies; the full national curriculum (English, Mathematics, Science, humanities, computing, art, PSHE and PE); and tarbiyyah — character, built around our RECIPE values. The exact subjects for each key stage are on the Curriculum page.'),
  ('Curriculum', 2, 'Which GCSEs do you offer, and with which exam boards?', 'English Language (AQA); English Literature and Arabic (Pearson Edexcel); Mathematics (board confirmed at course start); Science, Islamic Studies and Business (Pearson Edexcel International GCSE). History is not offered at GCSE. Pupils sit their exams as private candidates at an approved centre near home, and we guide you through registering.'),
  ('Curriculum', 3, 'Are the teachers qualified?', 'Yes. Every subject is taught by a qualified teacher with the relevant subject knowledge, an enhanced DBS check (or the overseas equivalent) and safeguarding training, and Qur''an is taught by experienced Qur''an teachers. Our Safer Recruitment Policy sets out every check we make.'),
  ('Curriculum', 4, 'How will I know how my child is doing?', 'Live progress on the Parent Portal (attendance, homework, Qur''an marks, merits and teacher messages), a written report each term, two parents'' evenings a year, and a weekly tarbiyyah note from the form tutor. Entry and annual standardised assessments give an objective benchmark.'),
  ('Curriculum', 5, 'Will my child be able to move back to a mainstream school?', 'Yes. Because we follow the national curriculum year by year and keep full records, pupils can transfer into any UK school at the matching year group, and we provide a transfer report.'),
  ('Islamic Studies', 1, 'How is Qur''an taught, and is hifz compulsory?', 'Qur''an is on the timetable every week in small groups set by ability, not by age: Qa''idah and early reading, fluent reading with tajweed, and memorisation. Every pupil memorises at a pace agreed with you; a full hifz track is available for pupils and families who want it to be central.'),
  ('Islamic Studies', 2, 'Will my child learn Arabic properly?', 'Yes. Arabic is taught as a language from Year 1, with reading, writing, speaking and grammar, so pupils connect with the Qur''an and classical texts directly, and it leads to GCSE Arabic in Years 10 and 11.'),
  ('Islamic Studies', 3, 'What is taught in Islamic Studies, and from which perspective?', 'Aqeedah, fiqh, seerah, hadith and akhlaq, taught from the Qur''an and Sunnah following the understanding of the early generations, in an age-appropriate way, leading to the Edexcel International GCSE in Islamic Studies. We are happy to talk through the syllabus with you.'),
  ('Islamic Studies', 4, 'How do you keep lessons appropriate for an Islamic setting?', 'Teachers set the tone: cameras and conduct follow our Online Conduct and RECIPE expectations, chat is controlled by the teacher, and one-to-one sessions are only ever scheduled through the Academy calendar, with parents told in advance and the session recorded. Ask us at an open evening about class arrangements for your child''s year group.'),
  ('Technology', 1, 'What equipment do we need?', 'A laptop or desktop (Windows or Mac) or an iPad with a webcam, microphone and headset; a reliable internet connection (a wired connection or good Wi-Fi); a quiet place to work; and Microsoft Teams, which is free. For secure assessments the device must run Safe Exam Browser. We check your setup with you during induction.'),
  ('Technology', 2, 'Where do lessons happen, and how does my child join?', 'Live lessons run on Microsoft Teams. Your child logs into the Pupil Portal, sees today''s timetable and presses Join; the portal takes them straight into the right lesson. Homework, resources and recordings live in the same place.'),
  ('Technology', 3, 'Is there a parent login?', 'Yes. Every family has a Parent Portal with the timetable, attendance, homework, Qur''an progress, reports, messages to teachers, invoices and anything that needs your signature. Accounts are created when you accept a place.'),
  ('Technology', 4, 'How is my family''s data protected?', 'Personal data is handled under UK GDPR, used only for your child''s education and the running of the school, and never sold. Lesson recordings are kept for safeguarding and catch-up and are not shared outside the Academy. The Data Protection and Recording of Live Lessons policies on the Policies page explain what we keep and for how long.'),
  ('SEND', 1, 'Do you support children with special educational needs?', 'Yes, within what an online school can provide: an individual support plan, adjustments in lessons, extra time and reader or scribe arrangements in assessments, and regular reviews with you. Tell us about your child''s needs in the application so we can discuss honestly what we can offer before you commit.'),
  ('SEND', 2, 'Can you support a child who is behind in reading, maths or Qur''an?', 'Yes. The entry assessment shows us where your child is, and Qur''an and Arabic groups are set by level, not age. Small classes make catch-up practical, and the portal shows you progress week by week.'),
  ('SEND', 3, 'Is the website and portal accessible?', 'Yes. Use the Aa button in the menu for larger text, easier reading and high contrast; the portal has the same options. Policies are available in accessible formats on request, and we welcome feedback on anything that is hard to use.'),
  ('Safeguarding', 1, 'How do you keep children safe online?', 'Every member of staff is DBS-checked and safeguarding-trained; live lessons are recorded for safeguarding purposes and run on Academy accounts only; one-to-one sessions are scheduled through the Academy calendar, with the parent informed and the session recorded; and a Designated Safeguarding Lead oversees it all. The Safeguarding and Online Safety policies are on the Policies page.'),
  ('Safeguarding', 2, 'Who do I contact if I am worried about something?', 'Your child''s form tutor for everyday matters, or the Designated Safeguarding Lead for any concern about a child''s safety — their contact details are on the Policies page and in the portal. Concerns and complaints follow the published Concerns and Complaints Policy.');
